def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers = list(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]

    def dist(a, b):
        return matrix[a][b]

    def route_cost(route):
        if not route:
            return 0
        c = dist(depot, route[0])
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        c += dist(route[-1], depot)
        return c

    def route_load(route):
        s = 0
        for v in route:
            s += demands[v]
        return s

    # Clarke-Wright savings with deterministic merges on compatible endpoints
    routes = [[c] for c in customers]
    loads = [demands[c] for c in customers]

    def build_pos(rs):
        pos = {}
        for ri, r in enumerate(rs):
            if not r:
                continue
            for pi, v in enumerate(r):
                pos[v] = (ri, pi, pi == 0, pi == len(r) - 1)
        return pos

    n = len(customers)
    savings = []
    for i in range(n):
        a = customers[i]
        for j in range(i + 1, n):
            b = customers[j]
            s = dist(depot, a) + dist(depot, b) - dist(a, b)
            savings.append((s, a, b))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    pos = build_pos(routes)
    active = len(routes)

    # Intra-route 2-opt (deterministic first improvement, limited)
    def two_opt(route):
        if not route:
            return route
        best_route = route
        best = route_cost(best_route)
        m = len(best_route)
        if m < 4:
            return best_route
        limit = min(80, m * m)
        it = 0
        improved = True
        while improved and it < limit:
            improved = False
            for i in range(0, m - 2):
                if improved or it >= limit:
                    break
                for k in range(i + 2, m - 1):
                    it += 1
                    new_r = best_route[:i + 1] + best_route[i + 1:k + 1][::-1] + best_route[k + 1:]
                    new_c = route_cost(new_r)
                    if new_c + 1e-9 < best:
                        best_route = new_r
                        best = new_c
                        improved = True
                        break
        return best_route

    for s, a, b in savings:
        if active <= 1:
            break
        if a not in pos or b not in pos:
            continue
        ra, pa, a_start, a_end = pos[a]
        rb, pb, b_start, b_end = pos[b]
        if ra == rb:
            continue
        if loads[ra] + loads[rb] > capacity:
            continue

        merged = None
        if a_end and b_start:
            merged = routes[ra] + routes[rb]
        elif a_start and b_end:
            merged = routes[rb] + routes[ra]
        elif a_end and b_end:
            merged = routes[ra] + routes[rb][::-1]
        elif a_start and b_start:
            merged = routes[rb][::-1] + routes[ra]
        if merged is None:
            continue

        # small targeted acceptance: ensure merge doesn't instantly blow up total cost
        old_total_part = route_cost(routes[ra]) + route_cost(routes[rb])
        new_total_part = route_cost(merged)
        if new_total_part <= old_total_part + 1e-12:
            routes[ra] = merged
            loads[ra] = loads[ra] + loads[rb]
            routes[rb] = []
            active -= 1
            pos = build_pos(routes)

    routes = [r for r in routes if r]
    loads = [route_load(r) for r in routes]

    def total_cost(rs):
        s = 0
        for r in rs:
            if r:
                s += route_cost(r)
        return s

    # Intra-route 2-opt
    for i in range(len(routes)):
        routes[i] = two_opt(routes[i])
    best_total = total_cost(routes)
    loads = [route_load(r) for r in routes]

    # Inter-route deterministic relocate (first improvement)
    max_moves = 600
    moves = 0
    improved = True
    while improved and moves < max_moves:
        improved = False
        for ri in range(len(routes)):
            if improved or moves >= max_moves:
                break
            r_from = routes[ri]
            if not r_from:
                continue
            m_from = len(r_from)
            for pi in range(m_from):
                if improved or moves >= max_moves:
                    break
                v = r_from[pi]
                new_from = r_from[:pi] + r_from[pi + 1:]
                new_from = two_opt(new_from)

                # try to move v to another route at best insertion position (deterministic first min)
                best_to = None
                best_to_cost = None
                best_to_ins = 0

                for rj in range(len(routes)):
                    if rj == ri or improved or moves >= max_moves:
                        continue
                    if loads[rj] + demands[v] > capacity:
                        continue
                    r_to = routes[rj]

                    local_best = None
                    local_best_cost = None
                    local_best_ins = 0
                    # insertion positions 0..len(r_to)
                    L = len(r_to)
                    for ins in range(L + 1):
                        cand_to = r_to[:ins] + [v] + r_to[ins:]
                        cand_to = two_opt(cand_to)
                        cand_to_cost = route_cost(cand_to)
                        if local_best_cost is None or cand_to_cost < local_best_cost - 1e-9:
                            local_best_cost = cand_to_cost
                            local_best = cand_to
                            local_best_ins = ins
                        elif abs(cand_to_cost - local_best_cost) <= 1e-9:
                            # deterministic tie
                            if ins < local_best_ins:
                                local_best_cost = cand_to_cost
                                local_best = cand_to
                                local_best_ins = ins

                    if local_best is None:
                        continue
                    if best_to_cost is None or local_best_cost < best_to_cost - 1e-9:
                        best_to_cost = local_best_cost
                        best_to = local_best
                        best_to_ins = local_best_ins
                    elif best_to_cost is not None and abs(local_best_cost - best_to_cost) <= 1e-9:
                        # deterministic tie by route index already ordered; keep first found

                if best_to is None:
                    continue

                new_to = best_to
                # find rj corresponding by scanning (deterministic; best_to equals constructed candidate for that rj)
                # To avoid nontrivial tracking, recompute rj choice by best_to_cost only: choose earliest that matches.
                target_rj = None
                for rj in range(len(routes)):
                    if rj == ri:
                        continue
                    if loads[rj] + demands[v] > capacity:
                        continue
                    if route_cost(two_opt(routes[rj][:])) == route_cost(routes[rj][:]):
                        pass
                    # match by comparing the constructed cost and ensuring new_to can only come from exact insertion
                    if abs(route_cost(new_to) - best_to_cost) <= 1e-9 and route_cost(routes[rj]) <= 10**18:
                        # accept the first route index with same cost; deterministic
                        target_rj = rj
                        break
                if target_rj is None:
                    continue

                cand_total = best_total - route_cost(routes[ri]) - route_cost(routes[target_rj]) + route_cost(new_from) + route_cost(new_to)
                moves += 1
                if cand_total + 1e-9 < best_total:
                    routes[ri] = new_from
                    routes[target_rj] = new_to
                    loads[ri] -= demands[v]
                    loads[target_rj] += demands[v]
                    best_total = cand_total
                    improved = True
                    break

        if improved:
            routes = [r for r in routes if r]
            loads = [route_load(r) for r in routes]

    # Inter-route deterministic swap (small additional edit, apply 2-opt on modified routes)
    swap_moves = 300
    moves = 0
    improved = True

    while improved and moves < swap_moves:
        improved = False
        R = len(routes)
        for ri in range(R):
            if improved or moves >= swap_moves:
                break
            r1 = routes[ri]
            if not r1:
                continue
            for rj in range(ri + 1, R):
                if improved or moves >= swap_moves:
                    break
                r2 = routes[rj]
                if not r2:
                    continue
                for i1 in range(len(r1)):
                    if improved or moves >= swap_moves:
                        break
                    v = r1[i1]
                    for i2 in range(len(r2)):
                        if improved or moves >= swap_moves:
                            break
                        w = r2[i2]
                        if loads[ri] - demands[v] + demands[w] > capacity:
                            continue
                        if loads[rj] - demands[w] + demands[v] > capacity:
                            continue

                        new_r1 = r1[:i1] + [w] + r1[i1 + 1:]
                        new_r2 = r2[:i2] + [v] + r2[i2 + 1:]
                        new_r1 = two_opt(new_r1)
                        new_r2 = two_opt(new_r2)

                        cand_total = best_total - route_cost(r1) - route_cost(r2) + route_cost(new_r1) + route_cost(new_r2)
                        moves += 1
                        if cand_total + 1e-9 < best_total:
                            routes[ri] = new_r1
                            routes[rj] = new_r2
                            loads[ri] = loads[ri] - demands[v] + demands[w]
                            loads[rj] = loads[rj] - demands[w] + demands[v]
                            best_total = cand_total
                            improved = True
                            break
        if improved:
            routes = [r for r in routes if r]
            loads = [route_load(r) for r in routes]

    return routes

